// PLACEHOLDER — this file is normally auto-generated by Supabase and must never be
// hand-edited once real: `npx supabase gen types typescript --project-id <ref> > src/integrations/supabase/types.ts`
// Replaced with the real generated file in the "set up live Supabase project" step,
// once the schema migrations (supabase/migrations/) have actually run. Until then,
// every table name is accepted with a loose `any` shape so the rest of the app
// compiles — this intentionally gives up row-level type-safety temporarily.

export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[]

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyTable = { Row: any; Insert: any; Update: any; Relationships: [] }
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyFunction = { Args: any; Returns: any }

export interface Database {
  public: {
    Tables: Record<string, AnyTable>
    Views: Record<string, never>
    // Loosened the same way as Tables above — added when the first .rpc()
    // call (record_inventory_transaction, Inventory.tsx) needed a Functions
    // entry that wasn't `never` to type-check. Real `supabase gen types` will
    // overwrite this with the actual function signature.
    Functions: Record<string, AnyFunction>
    Enums: Record<string, never>
    CompositeTypes: Record<string, never>
  }
}